"(function() {
    if (window.__sparkapp_perf_probe_installed) {
        return;
    }
    window.__sparkapp_perf_probe_installed = true;
    window.__sparkapp_start_time = Date.now();

    const perfLogger = {
        event: 'unknown',
        relativeMs: null,
        data: {}
    } => {
        if (window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.__sparkapp_perf) {
            window.webkit.messageHandlers.__sparkapp_perf.postMessage({
                event: event,
                relativeMs: relativeMs,
                data: data
            });
        }
    };

    let headParsed = false;
    let bodyParsed = false;

    const observer = new MutationObserver((mutations) => {
        mutations.forEach((mutation) => {
            mutation.addedNodes.forEach((node) => {
                if (node.nodeName === 'HEAD' && !headParsed) {
                    headParsed = true;
                    const relativeMs = Math.round(Date.now() - window.__sparkapp_start_time);
                    perfLogger({
                        event: 'HEAD_PARSED',
                        relativeMs: relativeMs
                    });
                }
                if (node.nodeName === 'BODY' && !bodyParsed) {
                    bodyParsed = true;
                    const relativeMs = Math.round(Date.now() - window.__sparkapp_start_time);
                    perfLogger({
                        event: 'BODY_PARSED',
                        relativeMs: relativeMs
                    });
                }
            });
        });
    });

    if (document.readyState === 'loading') {
        observer.observe(document, { childList: true, subtree: true });
    }

    document.addEventListener('DOMContentLoaded', () => {
        const relativeMs = Math.round(Date.now() - window.__sparkapp_start_time);
        perfLogger({
            event: 'DOM_CONTENT_LOADED',
            relativeMs: relativeMs
        });
        observer.disconnect();
    });

    window.addEventListener('load', () => {
        const relativeMs = Math.round(Date.now() - window.__sparkapp_start_time);
        perfLogger({
            event: 'PAGE_LOAD_COMPLETE',
            relativeMs: relativeMs
        });

        if (window.performance && window.performance.timing) {
            const timing = window.performance.timing;
            const perfData = {
                domContentLoadedEventEnd: timing.domContentLoadedEventEnd - timing.navigationStart,
                loadEventEnd: timing.loadEventEnd - timing.navigationStart,
                domInteractive: timing.domInteractive - timing.navigationStart,
                domComplete: timing.domComplete - timing.navigationStart
            };
            perfLogger({
                event: 'NAVIGATION_TIMING',
                relativeMs: relativeMs,
                data: perfData
            });
        }
    });

    if ('PerformanceObserver' in window) {
        const observer = new PerformanceObserver((list) => {
            for (const entry of list.getEntries()) {
                if (entry.entryType === 'paint' && entry.name === 'first-paint') {
                    const relativeMs = Math.round(entry.startTime);
                    perfLogger({
                        event: 'FIRST_PAINT',
                        relativeMs: relativeMs
                    });
                }
                if (entry.entryType === 'paint' && entry.name === 'first-contentful-paint') {
                    const relativeMs = Math.round(entry.startTime);
                    perfLogger({
                        event: 'FIRST_CONTENTFUL_PAINT',
                        relativeMs: relativeMs
                    });
                }
            }
        });
        observer.observe({ type: 'paint', buffered: true });
    }
})();"
